S = 'fill="#fff" stroke="#2b2150" stroke-width="6" stroke-linejoin="round" stroke-linecap="round"'
def el(t, **a): return '<%s %s %s/>' % (t, ' '.join('%s="%s"' % (k.replace('_', '-'), v) for k, v in a.items()), S)
def c(x, y, r): return el('circle', cx=x, cy=y, r=r)
def e(x, y, rx, ry): return el('ellipse', cx=x, cy=y, rx=rx, ry=ry)
def r(x, y, w, h, rx=0): return el('rect', x=x, y=y, width=w, height=h, rx=rx)
def p(d): return el('path', d=d)
def poly(pts): return el('polygon', points=' '.join('%s,%s' % t for t in pts))
def dot(x, y, rr=7): return '<circle cx="%s" cy="%s" r="%s" fill="#2b2150"/>' % (x, y, rr)
def line(d): return '<path d="%s" fill="none" stroke="#2b2150" stroke-width="6" stroke-linecap="round"/>' % d
import math
def star(cx, cy, R, rr, n=5):
    pts = []
    for i in range(n * 2):
        a = -math.pi / 2 + i * math.pi / n; k = R if i % 2 == 0 else rr
        pts.append((round(cx + k * math.cos(a), 1), round(cy + k * math.sin(a), 1)))
    return poly(pts)
