# حروف وأرقام
def glyph(ch, title, id, cat, fn='amiri-bold'):
    font = TTFont(ROOT + '/fonts/' + fn + '.woff'); gs = font.getGlyphSet(); cm = font.getBestCmap()
    g = gs[cm[ord(ch)]]; pen = SVGPathPen(gs); g.draw(TransformPen(pen, (1, 0, 0, -1, 0, 0)))
    from fontTools.pens.boundsPen import BoundsPen
    bp = BoundsPen(gs); g.draw(TransformPen(bp, (1, 0, 0, -1, 0, 0))); x0, y0, x1, y1 = bp.bounds
    sc = min(330 / (x1 - x0), 340 / (y1 - y0)); tx = 300 - (x0 + x1) / 2 * sc; ty = 225 - (y0 + y1) / 2 * sc
    add(id, cat, title, '<g transform="translate(%.1f %.1f) scale(%.4f)"><path d="%s" fill="#fff" stroke="#2b2150" stroke-width="%.1f" stroke-linejoin="round"/></g>' % (tx, ty, sc, pen.getCommands(), 6 / sc))
for ch, nm, i in [('أ', 'حرف الألف', 'alif'), ('ب', 'حرف الباء', 'baa'), ('ت', 'حرف التاء', 'taa'), ('ث', 'حرف الثاء', 'thaa'), ('ج', 'حرف الجيم', 'jeem'), ('ح', 'حرف الحاء', 'haa'), ('د', 'حرف الدال', 'dal'), ('ر', 'حرف الراء', 'raa'), ('س', 'حرف السين', 'seen'), ('م', 'حرف الميم', 'meem'), ('ن', 'حرف النون', 'noon')]:
    glyph(ch, nm, 'l-' + i, 'letter')
